package alcaldedigital.batalla;

import alcaldedigital.compartido.batalla.EstadoBatalla;
import alcaldedigital.compartido.batalla.EstadoBatalla.*;
import alcaldedigital.servidor.batalla.*;
import alcaldedigital.compartido.modelo.EstadoCiudad;
import java.util.*;
import java.nio.file.*;
import java.io.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class MotorBatallaTest {
    @TempDir Path tmp;
    static Vista escena(Vista v,Fase f,int patron,int reloj,Jugador[] js,List<Obstaculo> obs){return new Vista(v.id(),v.semilla(),v.tick(),f,patron/3,patron,reloj,v.jefe(),v.linea(),v.golpes(),v.elecciones(),js,obs,false,false,0,v.solo(),v.gano(),v.verificados(),v.rumores(),v.ciudad(),v.base(),v.mensaje(),v.historial(),v.publicaciones(),v.dificultad());}
    static Jugador jugador(Jugador j,float x,float y,int vidas,int inv){return new Jugador(j.nombre(),x,y,0,0,vidas,j.puntos(),inv,j.recuperaciones(),j.orientacion(),false,true,true,false);}
    static byte[] bytes(Vista v)throws Exception{var out=new ByteArrayOutputStream();EstadoBatalla.escribir(new DataOutputStream(out),v);return out.toByteArray();}
    @Test void conexionesListosEIntroNecesitanLosDosRoles(){var m=new MotorBatalla(5,false);m.conectar(1,"Periodista",true);m.orden(0,0,0,false,"LISTO",0);assertEquals(Fase.ESPERA,m.vista().fase());m.orden(1,0,0,false,"LISTO",0);assertEquals(Fase.INTRO,m.vista().fase());m.orden(0,0,0,false,"CONTINUAR",0);assertEquals(0,m.vista().linea());m.orden(1,0,0,false,"CONTINUAR",0);assertEquals(1,m.vista().linea());for(int n=0;n<8;n++){m.orden(0,0,0,false,"CONTINUAR",0);m.orden(1,0,0,false,"CONTINUAR",0);}assertEquals(Fase.OFICINA,m.vista().fase());}
    @Test void dañoIndividualYQuietudReal(){var base=new MotorBatalla(7,false).vista();Jugador[] js=base.jugadores();for(int i=0;i<2;i++)js[i]=jugador(js[i],550,500,5,0);var bala=new Obstaculo(500,460,100,100,0,0,1,0,0,100,-1);var m=MotorBatalla.restaurar(escena(base,Fase.ESQUIVA,1,1,js,List.of(bala)));m.orden(0,1,0,false,"",0);m.paso();assertEquals(4,m.vista().jugadores()[0].vidas());assertEquals(5,m.vista().jugadores()[1].vidas());
        var blanco=new Obstaculo(500,460,100,100,0,0,0,0,0,100,-1);m=MotorBatalla.restaurar(escena(base,Fase.ESQUIVA,0,1,js,List.of(blanco)));m.paso();assertEquals(4,m.vista().jugadores()[0].vidas());assertEquals(4,m.vista().jugadores()[1].vidas());m.paso();assertEquals(4,m.vista().jugadores()[0].vidas());}
    @Test void caídaCuentaComoMovimientoParaPaqueteCian(){var v=new MotorBatalla(1,false).vista();Jugador[] js=v.jugadores();js[0]=jugador(js[0],550,450,5,0);var obs=List.of(new Obstaculo(500,400,100,120,0,0,1,0,0,100,-1));var m=MotorBatalla.restaurar(escena(v,Fase.ESQUIVA,3,1,js,obs));m.paso();assertEquals(4,m.vista().jugadores()[0].vidas());}
    @Test void saltoCortoYGravedadLateral(){var v=new MotorBatalla(2,false).vista();Jugador[] js=v.jugadores();js[0]=jugador(js[0],500,603,5,1000);var largo=MotorBatalla.restaurar(escena(v,Fase.ESQUIVA,3,1,js,List.of()));var corto=MotorBatalla.restaurar(largo.vista());for(int t=0;t<12;t++){largo.orden(0,0,0,true,"",0);corto.orden(0,0,0,t==0,"",0);largo.paso();corto.paso();}assertTrue(largo.vista().jugadores()[0].y()<corto.vista().jugadores()[0].y());js[0]=jugador(js[0],988,500,5,1000);var lateral=MotorBatalla.restaurar(escena(v,Fase.ESQUIVA,9,1,js,List.of()));lateral.orden(0,0,0,true,"",0);lateral.paso();assertTrue(lateral.vista().jugadores()[0].x()<988);}
    @Test void hacesFijanObjetivoNoPersiguenDuranteAviso(){var v=new MotorBatalla(3,false).vista();Jugador[] js=v.jugadores();for(int i=0;i<2;i++)js[i]=jugador(js[i],500+i*200,530,5,1000);var m=MotorBatalla.restaurar(escena(v,Fase.ESQUIVA,6,0,js,List.of()));m.paso();var haz=m.vista().obstaculos().getFirst();float y=haz.y();assertEquals(0,haz.objetivo());assertTrue(haz.aviso()>0);m.orden(0,0,-1,false,"",0);for(int t=0;t<20;t++)m.paso();assertEquals(y,m.vista().obstaculos().getFirst().y());assertNotEquals(m.vista().jugadores()[0].y()-13,y);}
    @Test void guardarYRetomarConservaPatronesVidasPuntosYAzar()throws Exception{var v=new MotorBatalla(13,false).vista();Jugador[] js=v.jugadores();for(int i=0;i<2;i++)js[i]=jugador(js[i],500+i*200,530,5,9999);var m=MotorBatalla.restaurar(escena(v,Fase.ESQUIVA,7,1,js,List.of()));for(int i=0;i<170;i++)m.paso();var g=new GuardadoBatalla(tmp.resolve("partida.bin"));g.guardar(m);var r=g.cargar();assertArrayEquals(bytes(m.vista()),bytes(r.vista()));for(int i=0;i<60;i++){m.paso();r.paso();}assertArrayEquals(bytes(m.vista()),bytes(r.vista()));}
    @Test void turnoConjuntoNoAvanzaDosVecesYVerificarCambiaAVL(){var v=new MotorBatalla(2,false).vista();var m=MotorBatalla.restaurar(escena(v,Fase.TURNO,2,30,v.jugadores(),List.of()));m.orden(0,0,0,false,"ACCION",0);m.paso();assertEquals(Fase.TURNO,m.vista().fase());m.orden(1,0,0,false,"ACCION",1);m.paso();assertEquals(1,m.vista().ronda());assertEquals(Fase.AVISO,m.vista().fase());assertEquals(1,m.vista().verificados());assertEquals(4,m.publicaciones.cantidad());m.orden(1,0,0,false,"ACCION",2);m.paso();assertEquals(1,m.vista().ronda());}
    @Test void desconectarPausaYEntradasInvalidasNoAlteranPuntuacion(){var v=new MotorBatalla(5,false).vista();var m=MotorBatalla.restaurar(escena(v,Fase.ESQUIVA,0,10,v.jugadores(),List.of()));m.orden(0,Float.NaN,Float.POSITIVE_INFINITY,false,"PUNTOS",999999);m.conectar(1,"",false);long tick=m.vista().tick();for(int i=0;i<60;i++)m.paso();assertEquals(tick,m.vista().tick());assertEquals(0,m.vista().jugadores()[0].puntos());m.orden(0,0,0,false,"REANUDAR",0);assertTrue(m.vista().pausa());m.conectar(1,"Periodista",true);m.orden(1,0,0,false,"REANUDAR",0);m.paso();assertTrue(m.vista().tick()>tick);}
    @Test void rescateLimitadoYFinalPorDerrota(){var v=new MotorBatalla(2,false).vista();Jugador[] js=v.jugadores();js[0]=jugador(js[0],500,530,0,0);js[1]=jugador(js[1],760,530,5,999);var m=MotorBatalla.restaurar(escena(v,Fase.ESQUIVA,0,MotorBatalla.duracion(0)-1,js,List.of()));m.paso();assertEquals(2,m.vista().jugadores()[0].vidas());assertEquals(0,m.vista().jugadores()[0].recuperaciones());js[1]=jugador(js[1],760,530,0,0);m=MotorBatalla.restaurar(escena(v,Fase.ESQUIVA,0,10,js,List.of()));m.paso();assertEquals(Fase.EPILOGO,m.vista().fase());assertFalse(m.vista().gano());}
    @Test void repararAlCaidoNoLeExigeUnaAccionAusenteNiDuplicaElTurnoAlContinuar()throws Exception{
        for(int caido=0;caido<2;caido++){
            int vivo=1-caido;var v=new MotorBatalla(2026,false).vista();Jugador[] js=v.jugadores();
            for(int i=0;i<2;i++)js[i]=jugador(js[i],500+i*200,550,i==caido?0:3,0);
            var m=MotorBatalla.restaurar(escena(v,Fase.TURNO,5,0,js,List.of()));var g=new GuardadoBatalla(tmp.resolve("reparar-"+caido+".bin"));g.guardar(m);m=g.cargar();
            m.orden(vivo,0,0,false,"ACCION",2);assertDoesNotThrow(m::paso);
            assertEquals(Fase.AVISO,m.vista().fase());assertEquals(2,m.vista().ronda());assertEquals(1,m.vista().jugadores()[caido].vidas());assertEquals(0,m.vista().jugadores()[caido].puntos());assertEquals(12,m.vista().jugadores()[vivo].puntos());
            assertEquals(1,m.vista().historial().length);assertEquals(-1,m.vista().elecciones()[caido]);m.paso();assertEquals(2,m.vista().ronda());
        }
    }
    @Test void cadaPatronProduceAtaquesYTieneDuracionAcotada(){for(int p=0;p<15;p++){var v=new MotorBatalla(9,false).vista();Jugador[] js=v.jugadores();for(int i=0;i<2;i++)js[i]=jugador(js[i],500+i*200,530,5,99999);var m=MotorBatalla.restaurar(escena(v,Fase.ESQUIVA,p,0,js,List.of()));boolean genero=false;for(int t=0;t<MotorBatalla.duracion(p);t++){m.paso();genero|=!m.vista().obstaculos().isEmpty();}assertTrue(genero,"Patrón "+p+" vacío");assertNotEquals(Fase.ESQUIVA,m.vista().fase());}}
    @Test void resultadoSeGuardaUnaSolaVezYPropagaCiudadAutoritativa()throws Exception{var a=new MotorBatalla(2,true).vista();Vista fin=new Vista(a.id(),a.semilla(),a.tick(),Fase.FINAL,5,14,0,0,0,a.golpes(),a.elecciones(),a.jugadores(),List.of(),false,false,0,true,true,5,0,new int[]{60,56,53,53,53,12,16},a.base(),"Victoria",new String[0],new String[0]);var repo=new RepositorioResultados(tmp.resolve("campana.properties"));var c=repo.acreditar(fin,EstadoCiudad.inicial());assertEquals(56,c.confianza());assertEquals(c,repo.acreditar(fin,c));assertEquals(c,new RepositorioResultados(tmp.resolve("campana.properties")).ciudad(EstadoCiudad.inicial()));}
}
